WITH flattened AS (SELECT id, service, latency_ms, status_code, key, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) li AS key, value) SELECT CASE WHEN latency_ms >= 1890 THEN 'PREMIUM' ELSE 'STANDARD' END AS latency_ms_tier, CASE WHEN status_code >= 417 THEN 'HIGH' ELSE 'LOW' END AS status_code_tier, MAX(latency_ms) FILTER (WHERE key = 'trace') AS trace_max_latency_ms, COUNT_IF(key = 'region') AS region_events, SUM(latency_ms) AS total_latency_ms, MAX(status_code) FILTER (WHERE key = 'trace') AS trace_max_status_code, RANK() OVER (PARTITION BY CASE WHEN latency_ms >= 1890 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY MAX(status_code) FILTER (WHERE key = 'trace') DESC) AS trace_max_status_code_rank FROM flattened GROUP BY latency_ms_tier, status_code_tier HAVING total_latency_ms > 0;
